// Which abandoned checkouts get an email, and what offer each one gets. Rules, not AI:
// - only checkouts that weren't completed, have an email, have marketing consent, haven't been
//   contacted, and were left between abandoned_min_hours and abandoned_max_hours ago;
// - first-time customers with a cart of welcome_min_subtotal or more get the welcome code;
// - carts within free_shipping_nudge of the free-shipping threshold get a free-shipping nudge;
// - everyone else gets a friendly reminder with no offer.
// ---- lib-kettle.js (included by build.py): shared helpers for the Kettle & Fern workflows ----
const TZ = 'America/Los_Angeles';
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const settingsOf = items => Object.fromEntries(items.map(i => i.json).filter(r => r && r.key).map(r => [r.key, r.value]));
const parseJson = (s, d) => { try { return typeof s === 'string' ? JSON.parse(s) : (s === null || s === undefined ? d : s); } catch (e) { return d; } };
const nowIso = () => DateTime.now().setZone(TZ).toISO();
const newId = (prefix, n) => prefix + Array.from({ length: n || 5 }, () => 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random() * 32)]).join('');
const usd = n => '$' + (Math.round(Number(n || 0) * 100) / 100).toFixed(2).replace(/\.00$/, '');
const day = iso => iso ? DateTime.fromISO(String(iso), { zone: TZ }).toFormat('ccc d LLL') : '';

// OpenAI node (Responses API) output: the JSON object from the first output_text part, or null.
function aiJson(res) {
  if (!res || res.error) return null;
  const msg = (res.output || []).find(o => o && o.type === 'message');
  const part = msg && (msg.content || []).find(c => c && c.type === 'output_text');
  let t = part ? part.text : null;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
  return t && typeof t === 'object' ? t : null;
}

// Store-branded email: a header with the shop name, paragraphs, optional extra HTML (buttons, tables).
function emailHtml(store, paragraphs, extraHtml) {
  const p = paragraphs.filter(Boolean).map(t => '<p style="margin:0 0 14px;text-align:left">' + t + '</p>').join('');
  return '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:16px;line-height:1.6;color:#2b2a26;max-width:560px;text-align:left">'
    + '<div style="font-family:Helvetica,Arial,sans-serif;font-weight:700;font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#3f6b4a;margin:0 0 20px">' + esc(store) + '</div>'
    + p + (extraHtml || '') + '</div>';
}
// Plain text (blank lines between paragraphs) as escaped paragraphs for emailHtml.
const paragraphsOf = t => String(t || '').split(/\n{2,}/).map(p => esc(p).replace(/\n/g, '<br>'));
const button = (href, label) => '<p style="margin:6px 0 18px;text-align:left"><a href="' + esc(href) + '" style="display:inline-block;background:#3f6b4a;color:#fff;font-family:Helvetica,Arial,sans-serif;font-weight:600;padding:12px 22px;border-radius:999px;text-decoration:none">' + esc(label) + '</a></p>';
// ---- end lib-kettle.js ----
const s = settingsOf($('Read Settings').all());
const all = ($('Get Checkouts').first().json.checkouts || []);
const notes = Object.fromEntries(($('Get Products').first().json.products || []).map(p => [p.sku, p.notes]));
const now = Date.now();
const minH = Number(s.abandoned_min_hours || 1), maxH = Number(s.abandoned_max_hours || 48);
const threshold = Number(s.free_shipping_threshold || 50), nudge = Number(s.free_shipping_nudge || 15), welcomeMin = Number(s.welcome_min_subtotal || 60);
const skipped = [], send = [];
for (const c of all) {
  const hours = (now - Date.parse(c.created_at)) / 3600000;
  const why = c.completed ? 'completed the order' : !c.email ? 'no email' : !c.accepts_marketing ? 'no marketing consent' : c.contacted_at ? 'already contacted' : hours < minH ? 'too recent (' + Math.round(hours * 60) + ' min)' : hours > maxH ? 'too old (' + Math.round(hours / 24) + ' days)' : '';
  if (why) { skipped.push({ checkout_id: c.checkout_id, reason: why }); continue; }
  const items = parseJson(c.items_json, []);
  let offer = null;
  if (Number(c.orders_count || 0) === 0 && c.subtotal >= welcomeMin) offer = { type: 'code', code: s.welcome_code || 'WELCOME10', text: '10% off your first order with the code ' + (s.welcome_code || 'WELCOME10') };
  else if (c.subtotal < threshold && threshold - c.subtotal <= nudge) offer = { type: 'free_shipping', text: 'add ' + usd(threshold - c.subtotal) + ' more and shipping is free' };
  const prompt = 'Customer first name: ' + c.first_name + '\n\nItems in the cart:\n'
    + items.map(i => '- ' + i.qty + ' × ' + i.title + ' (shop notes: ' + (notes[i.sku] || 'none') + ')').join('\n')
    + '\n\nOffer: ' + (offer ? offer.text : 'none');
  send.push({ ...c, items, offer, prompt, hours: Math.round(hours * 10) / 10 });
}
return send.length ? send.map(json => ({ json: { ...json, skipped } })) : [{ json: { none: true, skipped } }];

